function objParse(obj) {
    return JSON.parse(obj, (n, v) => {
        if (typeof v == "string" && v.match("()")) {
            return eval(`(${v})`)
        }
        return v;
    })
}

(function (res) {
    result = {} //兼容搜索 for 循环
    result.novels = []
    // java.log(JSON.stringify(res))
    let isHtml = res.startsWith("<!DOCTYPE html>")
    if (isHtml) {
        let matchResult = baseUrl.match(new RegExp("pn|pixiv/novel|pixiv.net/novel"))
        if (matchResult == null) {
            return []
        }
        let id = baseUrl.match(new RegExp("\\d+"))[0]
        java.log(`匹配小说ID：${id}`)
        // res = util.getAjaxJson(util.urlNovelUrl(id))
        result.novels.push(util.getAjaxJson(util.urlNovelUrl(id)))
    } else {
        // 兼容 api 链接
        let isApiJson = baseUrl.match(new RegExp("pn|pixiv/novel|pixiv.net/novel"))
        if (isApiJson && typeof(JSON.parse(res)) === "object") {
            result.novels.push(JSON.parse(res))
        } else {
            result = JSON.parse(res)
            if (result.total === 0) {
                return []
            }
        }
    }


    // api更新后，需要使用 for 循环
    for (let i in result.novels) {
        res = result.novels[i]
        let prop = {}
        //为了兼顾导入书架直接走详情页逻辑
        //这里不能直接用book.xxx 来复用搜索页处理结果
        prop.author = res.userName
        prop.tags = res.tags
        prop.count = res.length
        prop.desc = res.desc
        prop.cover_url = util.urlCoverUrl(res.coverUrl)

        if (res.series === undefined || res.series === null) {
            prop.name = res.title
            prop.tags.unshift('单本')
            // prop.catalog = `https://api.furrynovel.ink/pixiv/novel/${res.id}/cache`
            prop.catalog = util.urlNovelUrl(res.id)

        } else {
            prop.name = res.series.title
            prop.tags.unshift('长篇')
            // prop.catalog = `https://api.furrynovel.ink/pixiv/series/${res.series.id}/cache`
            prop.catalog = util.urlSeriesUrl(res.series.id)
        }
        prop.tags = prop.tags.join(",")
        return prop
    }
})(result)

ruleContent.content:
@js:
var util = objParse(String(java.get("util")))

function objParse(obj) {
    return JSON.parse(obj, (n, v) => {
        if (typeof v == "string" && v.match("()")) {
            return eval(`(${v})`)
        }
        return v;
    })
}

(function (res) {
    res = JSON.parse(res)
    let content = res.content
    if (res.series !== null && res.desc !== undefined && res.desc !== "") {
        content = res.desc + "\n" + "——————————\n".repeat(2) + content
    }

    // 获取 [uploadedimage:] 的图片链接
    //将存在的pixiv图片链接替换为可访问的直连
    if (res.images !== undefined && res.images !== null) {
        Object.keys(res.images).forEach((key) => {
            content = content.replace(`[uploadedimage:${key}]`, `<img src="${util.urlCoverUrl(res.images[key].origin)}">`)
        })
    }

    // // 获取 [pixivimage:] 的图片链接
    let rex = /\[pixivimage:(\d+)]/gm
    let matched = content.match(RegExp(rex))
    if (matched) {
        for (let i in matched) {
            let illustId = matched[i].match(RegExp("\\d+"))
            content = content.replace(`${matched[i]}`, `<img src="${util.urlIllustOriginalUrl (illustId)}">`)
        }
    }



    // 替换 Pixiv 分页标记符号 [newpage]
    matched = content.match(RegExp(/[ 　]*\[newpage][ 　]*/gm))
    if (matched) {
        for (let i in matched){
            java.log(matched[i])
            content = content.replace(`${matched[i]}`, `${"<p>​<p/>".repeat(3)}`)
        }
    }

    // 替换 Pixiv 章节标记符号 [chapter:]
    matched = content.match(RegExp(/\[chapter:(.*?)]/gm))
    if (matched) {
        for (let i in matched) {
            let matched2 = matched[i].match(/\[chapter:(.*?)]/m)
            let chapter = matched2[1].trim()
            // content = content.replace(`${matched[i]}`, `${"<p>​<p/>".repeat(3)}${chapter}<p>​<p/>`)
            content = content.replace(`${matched[i]}`, `${chapter}<p>​<p/>`)
        }
    }

    // 替换 Pixiv 跳转页面标记符号 [[jump:]]
    matched = content.match(/\[jump:(\d+)]/gm)
    if (matched) {
        for (let i in matched) {
            let page = matched[i].match(/\d+/)
            content = content.replace(`${matched[i]}`, `\n\n跳转至第${page}节`)
        }
    }

    // 替换 Pixiv 链接标记符号 [[jumpuri: > ]]
    matched = content.match(/\[\[jumpuri:(.*?)>(.*?)]]/gm)
    if (matched) {
        for (let i in matched) {
            let matched2 = matched[i].match(/\[\[jumpuri:(.*?)>(.*?)]]/m)
            let matchedText = matched2[0]
            let urlName = matched2[1].trim()
            let urlLink = matched2[2].trim()
            // 阅读不支持超链接
            //content = content.replace(`${matchedText}`, `<a href=${urlLink}>${urlName}</a>`)
            if (urlLink === urlName) {
                content = content.replace(`${matchedText}`, `${urlName}`)
            } else {
                content = content.replace(`${matchedText}`, `${urlName}: ${urlLink}`)
            }
        }
    }

    // 替换 Pixiv 注音标记符号 [[rb: > ]]
    matched = content.match(/\[\[rb:(.*?)>(.*?)]]/gm)
    if (matched) {
        for (let i in matched) {
            let matched2 = matched[i].match(/\[\[rb:(.*?)>(.*?)]]/m)
            let matchedText = matched2[0]
            let kanji = matched2[1].trim()
            let kana = matched2[2].trim()
            // kana为中文，则替换回《书名号》
            var reg = new RegExp("[\\u4E00-\\u9FFF]+","g");
            if (reg.test(kana)) {
                content = content.replace(`${matchedText}`, `${kanji}《${kana}》`)
            } else{
                // 阅读不支持 <ruby> <rt> 注音
                // content = content.replace(`${matchedText}`, `<ruby>${kanji}<rt>${kana}</rt></ruby>`)
                content = content.replace(`${matchedText}`, `${kanji}（${kana}）`)
            }
        }
    }

    return content
})(result)

