ruleToc.chapterList:
ol li
@js:
var list=[],links=result.select("a"),regex=/(\w+-\w+)(?==")/g;
for (i=0;i<links.length;i++){
	link=links[i];
	aAttrs=String(link).match(regex);
	var text='',decUrl='';
	for (key of aAttrs){
		value=link.attr(key);
		value.includes("L2J")?decUrl=java.base64Decode(value):text=value.trim()
	}
	liAttrs=String(result[i]).match(regex);
	list.push({
		text:text,
		href:decUrl,
		num:result[i].attr(liAttrs[1])
	});
}
list.sort((a,b)=>a.num-b.num)

ruleToc.nextTocUrl:
#end@href
@js:
try{
	maxPage=0;
	tempUrl=String(result[0]).replace(/\/(\d+)\.html$/,(_match,_$1)=>{
		maxPage=_$1;
		return '/$page.html'
	});
	result=[];
	for (let i=2;i<=maxPage;i++){
		result.push(tempUrl.replace(/\$page/,i))
	}
	result
}catch(err){
	[]
}

ruleBookInfo.init:
@js:
(function(){
    let doc = org.jsoup.Jsoup.parse(result)
    let og = (selector) => doc.select('[property="og:' + selector + '"]').attr('content')
    return {
        name: og('novel:book_name'),
        author: og('novel:author'),
        kind: og('novel:category')
        +'•'+og('novel:status')
      +'•'+String(og('novel:update_time')),
        latest: og('novel:latest_chapter_name'),
        cover: og('image'),
        intro: og('description'),
        url:og('novel:read_url')
    }
})()

